// This drops the Indeed version if Seek already brought in the exact same job role/company
const items = $input.all();
const seen = new Set();
const uniqueItems = [];

for (const item of items) {
  const fingerprint = item.json['job_fingerprint'];

  if (fingerprint && !seen.has(fingerprint)) {
    seen.add(fingerprint);
    uniqueItems.push(item);
  }
}

return uniqueItems;

const supabaseResult = $input.all();

// If Supabase returned any row, it's a duplicate
if (supabaseResult.length > 0 && supabaseResult[0].json?.id) {
  return [{
    json: {
      ...$('Loop Over Items').item.json,
      __isDuplicate: true,
      __existingId: supabaseResult[0].json.id
    }
  }];
}

// Not a duplicate - pass through original job data
return [{
  json: {
    ...$('Loop Over Items').item.json,
    __isDuplicate: false
  }
}];

const items = $input.all();

return items.map(item => {
  const job = item.json;

  // Simply join the arrays into text strings so Airtable accepts them
  const formattedBullets = job.bulletPoints && job.bulletPoints.length > 0 
    ? "• " + job.bulletPoints.join("\n• ") 
    : "";

  const tagsString = job.tags ? job.tags.join(", ") : "";

  // This helper function removes spaces, dashes, and makes everything lowercase
  const cleanStr = (str) => {
    if (!str) return 'unknown';
    // Remove all non-alphanumeric characters (spaces, commas, hyphens)
    return String(str).toLowerCase().replace(/[^a-z0-9]/g, '');
  };

  // Build the fingerprint using the raw JSON fields
  // Note: Adjust 'job.companyName', 'job.title', 'job.location' if your raw keys differ between Seek/Indeed
  const cleanCompany = cleanStr(job.companyName);
  const cleanTitle = cleanStr(job.title);
  const cleanLocation = cleanStr(job.location);

  const fingerprint = `${cleanCompany}-${cleanTitle}-${cleanLocation}`;

  // Direct mapping from your exact JSON payload
  return {
    json: {
      "Job Title": job.title, 
      "Job ID": job.id, 
      "Salary": job.salary,
      "Work Type": job.workType,
      "Arrangement": job.workArrangements,
      "Job Link": job.jobLink,
      "Apply Link": job.applyLink,
      "Company": job.companyName,
      "Classification": job.classification,
      "Sub-Classification": job.subClassification,
      // Optional chaining (?.) handles the extraction cleanly without if/else blocks
      "Location": job.jobLocation?.[0]?.label,
      "Country": job.jobLocation?.[0]?.countryCode,
      "Listing Date": job.listingDate,
      "Teaser": job.teaser,
      "Highlights": formattedBullets,
      "Tags": tagsString,
      "Promoted": job.isPromoted,
      "Vectorized": false, // Staging for Part 2
      "Source": "Seek",
      "job_fingerprint": fingerprint
    }
  };
});

const items = $input.all();

return items.map(item => {
  const job = item.json;

  // 1. Format Work Type (Indeed provides an array like ["Casual"])
  const workTypeString = job.jobType ? job.jobType.join(", ") : "";

  // 2. Format Arrangement (Indeed uses isRemote or tags in attributes)
  let arrangement = "In-person";
  if (job.isRemote) {
    arrangement = "Remote";
  } else if (job.attributes && job.attributes.includes("Hybrid work")) {
    arrangement = "Hybrid";
  }

  // 3. Format Highlights (Combining Indeed's 'benefits' and 'attributes' into a bulleted list)
  const combinedHighlights = [...(job.benefits || []), ...(job.attributes || [])];
  // Remove duplicates just in case
  const uniqueHighlights = [...new Set(combinedHighlights)];
  const formattedHighlights = uniqueHighlights.length > 0 
    ? "• " + uniqueHighlights.join("\n• ") 
    : "";

  // 4. Format Tags
  const tagsString = job.attributes ? job.attributes.join(", ") : "";


  // This helper function removes spaces, dashes, and makes everything lowercase
  const cleanStr = (str) => {
    if (!str) return 'unknown';
    // Remove all non-alphanumeric characters (spaces, commas, hyphens)
    return String(str).toLowerCase().replace(/[^a-z0-9]/g, '');
  };

  // Build the fingerprint using the raw JSON fields
  // Note: Adjust 'job.companyName', 'job.title', 'job.location' if your raw keys differ between Seek/Indeed
  const cleanCompany = cleanStr(job.companyName);
  const cleanTitle = cleanStr(job.title);
  const cleanLocation = cleanStr(job.location);

  const fingerprint = `${cleanCompany}-${cleanTitle}-${cleanLocation}`;

  // Direct mapping to exactly match the Seek Schema
  return {
    json: {
      "Job Title": job.title || "", 
      "Job ID": job.jobKey || "", 
      "Salary":  job.salary.salaryText || "",
      "Work Type": workTypeString,
      "Arrangement": arrangement,
      "Job Link": job.jobUrl || "",
      "Apply Link": job.applyUrl || "",
      "Company": job.companyName || "",

      // Indeed uses 'occupation' array for classifications
      "Classification": job.occupation && job.occupation.length > 0 ? job.occupation[0] : "",
      "Sub-Classification": job.occupation && job.occupation.length > 1 ? job.occupation[1] : "",

      // Optional chaining handles missing locations cleanly
      "Location": job.location?.fullAddress || job.location?.formattedAddressShort || "",
      "Country": job.location?.countryCode || "AU",
      "Listing Date": job.datePublished || "",

      // Using descriptionText to retain the clean, HTML-free description
      "Teaser": job.descriptionText || "", 

      "Highlights": formattedHighlights,
      "Tags": tagsString,
      "Promoted": job.hiringDemand?.isUrgentHire || false, 
      "Vectorized": false, // Staging for Part 2
      "Source": "Indeed",   // Added Source Field
      "job_fingerprint": fingerprint
    }
  };
});
